BEGIN;





COMMIT;

SELECT 'clientes_carga' AS categoria, COUNT(*) AS quantidade FROM cliente WHERE cliente_email LIKE 'cliente%@gamelocadora.exemplo' UNION ALL SELECT 'jogos_carga', COUNT(*) FROM jogo WHERE EXISTS (SELECT 1 FROM exemplar WHERE exemplar_jogo_id = jogo_id AND exemplar_codigo LIKE 'GL-%') UNION ALL SELECT 'exemplares_carga', COUNT(*) FROM exemplar WHERE exemplar_codigo LIKE 'GL-%' UNION ALL SELECT 'alugueis_carga', COUNT(*) FROM aluguel WHERE aluguel_observacao LIKE 'Carga inicial GameLocadora %';
